var e={"29268u":`RoboKit — costruisci e simula un’auto robot`,qvztjl:`RoboKit — inizio del tutorial`,s42iv2:`academe.com.br (si apre in una nuova scheda)`,"16us7mj":`Lingua`,ktdb8o:`Impostazioni`,"198kuu7":`Banco di lavoro 3D`,ia581p:`Animazione`,j4z771:`Pausa`,wlqobg:`Pausa (Spazio)`,h23ysv:`Velocità di riproduzione`,r953rm:`Zoom`,"19blqjd":`Ingrandisci`,"110wpq2":`Riduci`,q5w460:`Vista`,bldqt5:`Vista esplosa (E)`,"44cnpg":`Vista inseguimento: segui l’auto da dietro (C)`,"13epjbk":`Mappa dall’alto dell’arena di prova`,j4zjee:`L’ostacolo selezionato`,yq1vr3:`Del centro dell’ostacolo, dal centro dell’arena, dove l’auto parte rivolta verso l’alto della mappa`,"19kd62s":`Personalizza l’arena`,l1a70i:`Personalizza l’arena: sposta, ruota e ridimensiona gli ostacoli`,"15n0apn":`Annulla l’ultima modifica (Ctrl+Z). Ctrl+Shift+Z la ripristina`,j4uzpn:`L’arena com’era in origine, con l’auto di nuovo alla partenza`,"84sbk0":`Lascia l’arena com’era (Esc)`,"1oy9vz":`Usa questa arena: la vista 3D viene ricostruita e la simulazione prosegue`,ium5z9:`Come decide il programma dell’auto`,vq0gg8:`Chiudi il diagramma di flusso`,s2tc63:`Chiudi (Esc)`,"13bjj4d":`Metti l’auto in Auto e guardala decidere`,gfubiu:`Come decide il programma: apri il diagramma di flusso`,"1gh0at8":`Passi del tutorial`,"61nq88":`Passi precedenti`,ga5x9q:`Passi successivi`,"1v1ybkn":`Guida`,"9anomo":`Avanti (W / ↑)`,bbake2:`Gira a sinistra (A / ←)`,bfl95g:`Stop (Spazio)`,iseiwq:`Gira a destra (D / →)`,"4o292l":`Retromarcia (S / ↓)`,"10qzszt":`Velocità dei motori`,"2yhdcy":`Modalità di guida`,"8m10x9":`Manuale (1)`,"1ogxhr7":`Evita ostacoli (2)`,"1i3ygcv":`Disattiva i motori (3)`,"1dlx0na":`Cicalino (B)`,isqcd9:`Angolo del servo`,"29ulgm":`Uscita seriale`,"1l0xxoj":`Chiudi`,"2r1h4p":`Connessione`,cwepyb:`Caricamento…`,"10iu545":`RoboKit ha bisogno di JavaScript per funzionare.`,"120y7gz":`Progettato da`,"1hpelzf":`Scheda`,"1j2fqe6":`BANCO DI LAVORO`,"17d8vhd":`Passo 1 · Raccogli i pezzi`,gqo5v1:`Simulatore`,"1py6ulk":`Clicca per ispezionare`,"1ms3o1u":`Distanza`,"2w2xwg":`Velocità`,n44ilu:`Modalità`,"1d2vfr6":`Servo`,"152va0w":`Simulazione in pausa`,"11i7yk1":`Clicca un ostacolo per selezionarlo.`,"1a4x3zw":`Dimensioni`,"1kpdcfp":`Lunghezza`,gfxz9b:`Larghezza`,s3robe:`Diametro`,"7puwki":`Altezza`,kbxnhn:`Rotazione`,"7nkn2r":`Posizione, dalla partenza`,v1hcj2:`Avanti`,"1vf2pel":`A destra`,"1xakelj":`Maiusc`,"1esrfu8":`passi di 5 cm, 15°`,yvgdmk:`Alt`,"1w55ans":`dimensioni dal centro`,"1xzs12p":`sposta ·`,"14bbmnu":`ruota`,g7xa5b:`Arena · 3 × 3 m`,vmlwpb:`Annulla`,"2zps2o":`Ripristina`,ew9em3:`Annulla`,lewgh4:`Salva`,"1vz8dhj":`Come decide il programma`,m76rx7:`Scegli un riquadro per vederne il codice`,"1hnif0x":`Flusso del programma`,"11rknnz":`Dal vivo`,"540b06":`Auto`,"1fr6xqr":`Raccogli i pezzi`,"1wu7r43":`Manuale`,ky4lc5:`Stop`,"152av8f":`Attuatori`,"1df7dln":`Cicalino`,pksfl2:`guida ·`,"1hrh82t":`Spazio`,"9zyeew":`stop ·`,jw8yab:`modalità ·`,j4ckle:`cicalino ·`,kzo6rh:`inseguimento`,mcpijf:`Monitor seriale`,"1aeugy":`Pulisci`,"1jgmzoq":`← Indietro`,c9ljxw:`passi`,"1padbm0":`Avanti`,g6g542:`Torna al passo`,"1k7z1pa":`Esc`,dpexcn:`Specifiche`,"8f4gnm":`Vai al passo`,qy3p54:`IMPOSTAZIONI`,"12znfuf":`Il passo di guida si collega a`,"17rhf7d":`Auto vera (Wi-Fi dell’ESP32)`,dsq8ip:`Indirizzo dell’auto`,"1ihj7t4":`Schermo e audio`,oh792y:`Suona il cicalino dagli altoparlanti`,"1bxmuya":`Mostra il fascio a ultrasuoni`,"1gxdv01":`La telecamera segue l’auto`,"9mmtn3":`Azzera la simulazione`,"1k6e5zv":`Applica`,"1iptqu5":`URL non valido “{url}”`,"12bfr2h":`L’URL deve iniziare con ws:// o wss://`,"1s22nop":`Connessione a {url}`,"1q17yrm":`Nuovo tentativo tra {s} s`,hsi0bv:`Nessun dato dall’auto`,ye8ewg:`Connesso`,"1puhp9v":`Connessione…`,y1y3f2:`Nessun dato`,ci4tze:`Disconnesso`,"1fmx9lv":`Errore di connessione`,"19wtqq3":`Connesso · {board}`,"1b4ym3j":`Simulatore integrato`,bgnl0z:`Preparazione della grafica`,"39rjx0":`Pronto`,"1ruee97":`Il banco 3D non è riuscito ad avviarsi. Serve WebGL: prova un altro browser o attiva l’accelerazione hardware.`,xa5swu:`ARENA DI PROVA`,"18xfupg":`Guida con i comandi a destra`,khccvm:`Guida con W A S D o con i comandi a destra`,vhwww6:`Passo {n} · {title}`,"1i98668":`Costruzione dell’auto`,y9b5jm:`Disposizione dei pezzi`,qzfxj5:`Mostra la riga {n} sul banco`,pj86x7:`Mostra questo sul banco`,"13bzcw5":`Copiato`,"8gdme8":`Seleziona e copia`,s6g5lw:`Copia`,"1bstp0v":`Distinta dei materiali`,"1g4j0cl":`Ti servirà`,"15cdqf0":`Attrezzi`,"1wrxvmg":`Cosa fare`,"1x0ptmh":`Mappa dei pin · {board}`,"1go9otx":`Sketch`,zvnhd5:`Sketch`,t8quxl:`Scarica`,na9qmv:`Se qualcosa non va`,"5mau71":`Nota`,"1xh5jos":`{kicker} · Passo {n} di {total}`,slbawy:`Avanti: {step} →`,"7rhhil":`Ricomincia ↺`,"1mtyvb1":`Passo {n}: {step} · {done} / {total} spuntati`,"4x1xaj":`Passo {n}: {step}`,d2gue0:`Scatola di cartone`,"1xebpbq":`Blocco di legno`,hi63vm:`Lattina`,"14yz9o9":`Vaso da fiori`,"1g6nbya":`Deve restare dentro le pareti.`,v23nvk:`Il punto di partenza dell’auto deve restare libero.`,"1d1sqge":`L’auto si trova lì.`,sjcnug:`Due ostacoli non possono occupare lo stesso posto.`,"1rjq9tt":`Trascina un ostacolo per spostarlo. Le maniglie quadrate ne cambiano le dimensioni, quella rotonda lo ruota.`,qaws2z:`L’arena vista dall’alto. Clicca un ostacolo per selezionarlo, trascinalo per spostarlo. Con la tastiera: Pag giù e Pag su selezionano un ostacolo, le frecce lo spostano, R lo ruota.`,km6rtw:`Ostacolo`,v6zgjh:`L’arena com’era in origine. Salvando, l’auto torna alla partenza.`,"1bneya5":`Ogni giro inizia qui`,"1gvmqkj":`Decisione`,"2wk0tb":`Azione`,ltbyq8:`sì`,r90oai:`no`,"10pfeta":`{file} · righe {lines}`,"1mv69ab":`{file} · riga {lines}`,v5glvz:`nessuna eco`,"1y6bn7c":`sinistra {left} · destra {right}`,"17yvayv":`Strada libera: avanti`,g8loky:`{reading} davanti · si ferma sotto {stop} cm`,"1qpxp29":`Stop · LED acceso · bip`,lman68:`ostacolo a {reading} · sotto {stop} cm`,"4e4gg4":`Indietreggiata: si guarda intorno`,"1x1kke3":`la lettura non cambiava da {s} s`,"1pc4lzp":`Retromarcia fatta: guarda di nuovo`,"11qad25":`entrambi i lati erano troppo stretti per girare`,dfsfd7:`Bloccata: indietreggia`,eic5lt:`lettura invariata da {s} s`,n7w5mt:`Niente spazio per girare: retromarcia`,etina8:`{sides} · sotto {tight} cm`,crgp5w:`Guarda a destra`,vto9jk:`legge {reading}`,"1xubspn":`Guarda a sinistra`,"92dcjq":`destra {right} · sinistra legge {reading}`,cfs13v:`C’è spazio per girare?`,h7zzeh:`{sides} · servono {tight} cm`,qlw2zr:`Gira di nuovo a sinistra`,"1fd6gkc":`Gira di nuovo a destra`,"1hj21ci":`bloccata subito dopo una svolta: stesso verso`,"1jk1kpr":`Gira a sinistra`,u6ps9c:`Gira a destra`,"1uvg70v":`Auto è spento`,"1bbdvwo":`Vista dal vivo: solo l’auto simulata`,"1fj8dwo":`passa ad Auto per vedere l’auto decidere`,"14g7i3l":`un’auto vera riporta le letture, non il passo della sua routine`,"15nlm70":`Torna al passo {n} · {step}`,"1i8tm8j":`Montato in <b>questo passo</b>`,rpu2qi:`Montato nel <b>passo {n} · {step}</b>`,"1b4o3fw":`Vai al passo {n} →`,y322vs:`Lingua: {name}`,bk85tv:`Riproduci`,"1x4eyna":`{action} (Spazio)`,gpdo6z:`Usa un indirizzo ws:// o wss://, ad es. ws://192.168.4.1:81/`,"1iquufv":`Prima collegati alla rete Wi-Fi dell’auto. Vedi README.md per il formato dei messaggi che il firmware deve usare.`,njqkz2:`Inserisci un URL WebSocket, ad es. ws://192.168.4.1:81/`,nrzvmi:`Guida un’auto simulata in un’arena di prova, senza hardware.`,cegybp:`Pezzi`,wv4sck:`Preparazione`,"7z3mbb":`Tutto per un rover a quattro ruote con una “testa” a ultrasuoni che può guardarsi intorno. Disponi i pezzi così e spuntali uno a uno. Passa il mouse su una riga per trovarla sul tappetino, o clicca un pezzo per i dettagli.`,"1x97es5":`Carica le celle 18650 con un vero caricatore Li-ion prima di iniziare e usa celle protette: una cella non protetta può erogare decine di ampere in un cortocircuito.`,"13wu8qd":`Telaio in acrilico: piano inferiore, intermedio e superiore`,"9z9vwl":`Motoriduttori TT (3–6 V, 1:48) con 8 staffe in acrilico a T, 8 bulloni M3 × 30 e dadi`,"1qr4ely":`Ruote, 65 mm`,cmzolq:`Modulo driver per due motori L9110S`,"1qgfn27":`Arduino UNO R3 + Sensor Shield V5 + cavo USB`,"15cdntm":`ESP32 DevKit V1 (30 pin) + scheda di espansione + cavo USB`,mfnvxi:`Sensore a ultrasuoni HC-SR04 + la sua staffa per servo e viti`,"15iavp3":`Micro servo SG90 con squadrette e viti`,"1allzrf":`Celle Li-ion 18650 (protette) + portabatterie a 2 posti in serie con fili`,xooybo:`Interruttore a slitta, LED rosso da 10 mm, resistenza da 220 Ω, cicalino attivo da 5 V`,"1csc29i":`Interruttore a slitta, LED rosso da 10 mm, cicalino attivo da 5 V, transistor NPN (PN2222A o S8050), resistenze da 220 Ω, 2 × 1 kΩ e 2 kΩ`,"17dpcif":`Spinotto DC a barile con morsetti a vite, 5.5 × 2.1 mm`,bozwcy:`20 cavetti jumper femmina–femmina da 15 cm; filo di collegamento rosso e nero; 16 distanziali in ottone M3 femmina–femmina (8 × 25 mm, 4 × 15 mm, 4 × 10 mm), 32 viti M3 × 6 mm, nastro biadesivo in gommapiuma, guaina termorestringente`,"5z6ae7":`Saldatore, stagno`,"1xhh6dp":`fili dei motori, l’interruttore, i fili del LED e del cicalino`,"11dguvz":`Cacciaviti piccoli`,"1b1pnob":`a croce per le viti M3, piatto per i morsetti del driver e dello spinotto`,"1ligzav":`Tronchesine / spelafili`,"3pb5yx":`tagliare e spelare il filo di collegamento e i cavetti`,"1avt53n":`Multimetro`,"1slxnnr":`controllare la polarità prima di dare corrente`,"100w2b7":`Caricatore Li-ion`,"64j96q":`per le celle 18650`,"1heknmc":`Computer, Arduino IDE`,"1mo2nzj":`per caricare il codice al passo 9`,t9gk37:`Motori`,"15i6udf":`Montaggio`,"1fofbt3":`Motori e ruote`,"15llile":`Ogni motore TT è un piccolo motore DC che aziona un riduttore in plastica 1:48. I due motori di sinistra e i due di destra girano sempre insieme, come i cingoli di un carro armato: l’auto sterza facendo andare i due lati a velocità diverse.`,k5fimq:`Il rosso sulla linguetta interna di ogni motore è ciò che ti permette di unire rosso con rosso al passo 4: il motore anteriore e quello posteriore di un lato sono uno di fronte all’altro, quindi le loro linguette interne hanno lo stesso ruolo. Le linguette sono sottili e si spezzano se si tira un filo, quindi fissa con nastro ogni coppia di fili al suo motore. I fili restano in piedi al centro perché la lunga fessura del piano intermedio possa scendere su di essi al passo 3.`,"7fte4n":`Piano inferiore`,rbcm1a:`Motoriduttori TT`,sjfn38:`Staffe motore in acrilico a T`,"732lu":`Bulloni M3 × 30 e dadi`,skq14t:`Ruote`,"1s4rmq":`Appoggia i quattro motori al loro posto sul piano inferiore, alberi verso l’esterno ed estremità dei motori verso il centro. Salda due fili lunghi circa 15 cm a ciascuno: il rosso sulla linguetta più vicina al centro dell’auto, il nero su quella più vicina alla ruota. Tieni gli otto fili in piedi insieme al centro del piano.`,"1mrwedd":`Solleva il piano. Da sotto, spingi una staffa su attraverso la fessura sul lato interno di ogni motore e un’altra nella tacca sul bordo del piano, all’esterno. Fai passare due bulloni M3 × 30 attraverso staffa, riduttore e staffa, teste dal lato della ruota, e stringi un dado su ciascuno.`,"13sq8kw":`Infila una ruota su ogni albero. L’albero ha due facce piane che si incastrano nel mozzo, quindi la ruota non può slittare.`,"199dyzl":`Piani`,qr73r6:`Impila i piani`,kig8cy:`I distanziali in ottone sollevano il piano intermedio di 25 mm sopra quello inferiore, sopra i riduttori alti 22 mm, e danno all’elettronica un pavimento piatto. Ogni distanziale è filettato alle due estremità: una vite sale attraverso il piano sottostante, un’altra scende attraverso ciò che sta sopra.`,"1w8a39y":`L’acrilico si crepa se lo stringi troppo, quindi basta che sia saldo. I telai variano: se il tuo non ha un foro dove serve al controller, due distanziali e un cuscinetto di nastro in gommapiuma sotto l’altra estremità tengono ben ferma una scheda.`,jcqip:`Piano intermedio`,u6l9bq:`Distanziali in ottone M3 × 25 mm`,"4cdagt":`Distanziali in ottone M3 × 10 mm (per il controller)`,xaqs1y:`Distanziali in ottone M3 × 15 mm (per il piano superiore)`,"300byl":`Viti M3 × 6 mm`,tezznv:`Avvita otto distanziali da 25 mm sul piano inferiore, quattro per lato, ciascuno su una vite inserita da sotto.`,"70hnlv":`Prima di montare il piano intermedio, finché ci arrivi ancora da sotto, fissa i quattro distanziali da 10 mm sotto i fori di montaggio del controller (tieni la scheda in posizione per vedere quali fori del piano coincidono) e i quattro distanziali da 15 mm agli angoli della metà posteriore, ciascuno con una vite da sotto.`,"1tynoxv":`Abbassa il piano intermedio sui distanziali da 25 mm, facendo passare i fili dei motori su per la lunga fessura centrale mentre scende, e avvitalo.`,"1n5adbz":`Driver`,"1ri406w":`Monta il driver dei motori`,"5n5nar":`Un pin di un microcontrollore non dovrebbe fornire più di circa 20 mA, ma un motore TT assorbe qualche centinaio di mA in marcia e oltre 1 A in stallo. Il modulo L9110S ha due ponti H che commutano la corrente della batteria attraverso i motori e possono invertirla.`,"1uicxnj":`Quale vite di un morsetto riceve quale coppia per ora non importa: il test del cablaggio al passo 9 mostra se un lato gira al contrario o se una ruota gira contro la compagna. Lascia libero il connettore a 6 pin (B-IA, B-IB, GND, VCC, A-IA, A-IB): l’alimentazione arriva al passo 7 e i segnali al passo 8. L’L9110S regge 800 mA per canale e qui ogni canale pilota due motori: va bene per la guida normale, ma non tenere le ruote bloccate. Se i chip si scaldano, un modulo TB6612FNG (1.2 A per canale) è un sostituto più robusto.`,utkklb:`Cuscinetto di nastro biadesivo in gommapiuma`,syij08:`Attacca il driver al piano intermedio con il nastro in gommapiuma, davanti ai distanziali del controller e a sinistra del centro: il connettore a 6 pin verso il bordo sinistro dell’auto, i morsetti a vite verso il centro dell’auto.`,"15kkcap":`Piega i fili in avanti lungo il piano e portali ai morsetti del driver. Attorciglia insieme i due fili rossi dei motori di sinistra e insieme i loro due fili neri, e avvita le due coppie in MOTOR-A, il morsetto più vicino al controller. Fai lo stesso con i fili dei motori di destra in MOTOR-B.`,"18rvg69":`Controller`,ync8b9:`Monta l’Arduino UNO`,"1u68uls":`Monta l’ESP32`,ertyxs:`L’Arduino UNO (ATmega328P, 16 MHz, logica a 5 V) esegue il tuo sketch. Sopra si innesta un Sensor Shield V5 che dà a ogni pin il proprio connettore G / V / S (massa, 5 V e segnale), perché il connettore di alimentazione dell’UNO ha un solo pin a 5 V da condividere tra servo e sensore.`,"1p7bu2t":`L’ESP32 (dual-core, fino a 240 MHz, Wi-Fi e Bluetooth, logica a 3.3 V) esegue il tuo sketch e permette a RoboKit di guidare l’auto vera via Wi-Fi. La sua scheda di espansione aggiunge una presa DC con regolatore e un connettore G / V / S per ogni pin.`,ii2aq7:`I pin dell’UNO sono a 5 V, quindi sensore e servo si collegano direttamente allo shield.`,"1ghuj2z":`I pin dell’ESP32 lavorano a 3.3 V e non tollerano i 5 V, quindi l’uscita Echo del sensore riceve un partitore di tensione al passo 8.`,t5ws5g:`ESP32 DevKit V1 (30 pin)`,"1tu8qz5":`Scheda di espansione ESP32 (30 pin)`,"14w4gx0":`Avvita l’UNO sui quattro distanziali da 10 mm dietro il driver, con le prese USB e DC rivolte verso il lato sinistro dell’auto.`,hw767j:`Innesta il Sensor Shield V5 sull’UNO con ogni pin nel suo zoccolo. Lascia montato il jumper SEL, così i pin V dello shield prendono i 5 V dall’UNO, e non collegare nulla al morsetto a vite dello shield.`,"1opbgrl":`Avvita la scheda di espansione sui quattro distanziali da 10 mm dietro il driver, con la presa DC rivolta verso il lato sinistro dell’auto.`,"1xxnsy2":`Inserisci il DevKit nei due zoccoli in modo che ogni nome di pin corrisponda al nome stampato accanto allo zoccolo. Una scheda spostata di un pin mette l’alimentazione sui pin sbagliati.`,ua2sfx:`Imposta il jumper dei pin V su 5 V, perché servo, HC-SR04 e cicalino hanno bisogno di 5 V. Le schede di espansione variano, quindi controlla le marcature del jumper sulla tua.`,"1jzloyj":`Sensore`,"19ot7f3":`Testa del sensore`,jii9ss:`L’HC-SR04 emette un impulso a ultrasuoni a 40 kHz e cronometra l’eco: distanza in cm ≈ tempo dell’eco in µs ÷ 58. Misura da 2 cm a circa 4 m entro un fascio largo circa 15°. Montato su un servo SG90, può guardare a sinistra e a destra prima che l’auto giri.`,"1s5nsw8":`Per centrare il servo, collegalo al connettore A5 dello shield (marrone su G) e carica uno dei due sketch del passo 9: entrambi lasciano la testa a 90°. Girare a forza l’albero di uscita può spanare gli ingranaggi in plastica. Montato in questo verso, i pin del sensore sono GND, Echo, Trig, VCC da sinistra, visti di fronte.`,"3b6msg":`Per centrare il servo, collegalo al connettore GPIO 23 (marrone su G, V a 5 V) e carica il firmware del passo 9, il cui setup() chiama servoWrite(90). Girare a forza l’albero di uscita può spanare gli ingranaggi in plastica. Montato in questo verso, i pin del sensore sono GND, Echo, Trig, VCC da sinistra, visti di fronte.`,"2934zx":`Micro servo SG90, squadretta singola e viti`,"1o4q0ha":`Staffa per servo dell’HC-SR04, con le sue viti`,"87cfw2":`Sensore a ultrasuoni HC-SR04`,"1bhe6w2":`Tieni il servo sopra il foro rettangolare nella parte anteriore del piano intermedio, albero di uscita in alto e sulla linea centrale dell’auto. Fai passare il connettore giù dal foro, indietro sotto il piano e su per la piccola fessura dietro, e tira il cavo finché il connettore non è sul piano accanto al controller. Poi abbassa il servo nel foro, con il cavo che scende dalla tacca all’estremità, spingi il cavo in eccesso sotto il piano, lontano dall’albero del motore, e avvita le due alette del servo al piano.`,"7x26fs":`Centra il servo, poi infila una squadretta singola sul suo albero, rivolta in avanti, e fissala con la vite della squadretta.`,"3f8bcm":`Avvita la staffa alla squadretta, dritta e rivolta in avanti.`,"178kb38":`Avvita l’HC-SR04 sul davanti della staffa attraverso i due fori d’angolo di un lato lungo, con quel lato in basso e i pin in alto: così i fili escono verso l’alto, lontano dal servo.`,"1jamndy":`Alimentazione`,tboesy:`Due celle 18650 in serie danno 7.4 V nominali (8.4 V cariche, circa 6 V scariche). L’interruttore interrompe il filo + della batteria. Tutto si incontra in uno spinotto DC con morsetti a vite: i due fili della batteria entrano lì, lo spinotto alimenta l’UNO dalla sua presa DC, il cui regolatore fornisce i 5 V della logica, e altri due fili dagli stessi morsetti alimentano il driver dei motori. Il driver non può prendere l’alimentazione dai pin a 5 V dello shield: vengono dal piccolo regolatore dell’UNO, che quattro motori sovraccaricherebbero. I pezzi che hanno bisogno di fili saldati li ricevono al banco, prima di andare sull’auto: infila prima un pezzo di guaina termorestringente sul filo, poi restringila sulla saldatura.`,r69l9i:`Due celle 18650 in serie danno 7.4 V nominali (8.4 V cariche, circa 6 V scariche). L’interruttore interrompe il filo + della batteria. Tutto si incontra in uno spinotto DC con morsetti a vite: i due fili della batteria entrano lì, lo spinotto alimenta la scheda di espansione dalla sua presa DC, i cui regolatori forniscono i 5 V e i 3.3 V della logica, e altri due fili dagli stessi morsetti alimentano il driver dei motori. Il driver non può prendere l’alimentazione dai pin a 5 V della scheda: vengono dal suo piccolo regolatore, che quattro motori sovraccaricherebbero. I pezzi che hanno bisogno di fili saldati li ricevono al banco, prima di andare sull’auto: infila prima un pezzo di guaina termorestringente sul filo, poi restringila sulla saldatura.`,"175zcey":`Controlla due volte la polarità prima di inserire le celle: la presa dell’UNO ha il positivo al centro, e il morsetto + dello spinotto è il suo pin centrale (controlla con un multimetro). Ricarica quando il pacco scende a circa 7 V, sotto i quali il regolatore dell’UNO non riesce a mantenere i 5 V. Se non si accende nessun LED, spegni subito e controlla il cablaggio prima di riprovare. Il LED e il cicalino restano al banco fino al passo 8.`,t60ux3:`Controlla due volte la polarità prima di inserire le celle: la maggior parte delle schede di espansione ha il positivo al centro, ma controlla il simbolo vicino alla presa, e il morsetto + dello spinotto è il suo pin centrale (controlla con un multimetro). Ricarica quando il pacco scende a circa 7 V. Se non si accende nessun LED, spegni subito e controlla il cablaggio prima di riprovare. Il LED e il cicalino restano al banco fino al passo 8.`,mvli44:`Piano superiore + 4 viti M3 × 6 mm`,"1dowjmo":`Portabatterie 2 × 18650 con fili, 2 celle`,"83x4u2":`Interruttore a slitta`,"1in9b4e":`Spinotto DC a barile con morsetti a vite (centro +)`,l8wrh1:`LED rosso da 10 mm + resistenza da 220 Ω`,"24gtky":`Cicalino attivo da 5 V`,"14zuroc":`Cicalino attivo da 5 V, transistor NPN + resistenza da 1 kΩ`,"1pgj6ai":`Nastro in gommapiuma, guaina termorestringente, 4 cavetti da tagliare: 2 rossi, 2 neri`,"1ewjpxi":`Nastro in gommapiuma, guaina termorestringente, 5 cavetti da tagliare: 2 rossi, 2 neri, 1 arancione`,y2bs3a:`Appoggia il piano superiore sui quattro distanziali da 15 mm e avvitalo.`,anc24f:`Al banco, taglia il filo rosso del portabatterie a circa 2 cm dal portabatterie. Salda l’estremo del portabatterie a un pin esterno dell’interruttore, e 10 cm del pezzo tagliato al pin centrale.`,"1mixan6":`Tieni il portabatterie sopra il piano superiore, con i fili verso la sinistra dell’auto. Fai passare il filo nero giù dal foro sul bordo sinistro del piano e portalo in avanti lungo il piano intermedio mentre abbassi il portabatterie. Attacca il portabatterie con due strisce di nastro in gommapiuma, e l’interruttore di lato sul bordo sinistro del piano, leva verso l’esterno. Poi porta il filo rosso in avanti, oltre l’angolo anteriore del piano. Entrambi i fili devono finire accanto alla presa DC del controller.`,"1xim7b6":`Taglia un cavetto rosso e uno nero a 12.5 cm da un’estremità. Innesta il connettore del pezzo rosso lungo sul pin VCC del driver e quello del nero lungo su GND, e portali indietro lungo il bordo sinistro del piano intermedio fino alla presa.`,"1200i":`Taglia un cavetto rosso e uno nero a 11 cm da un’estremità. Innesta il connettore del pezzo rosso lungo sul pin VCC del driver e quello del nero lungo su GND, e portali indietro lungo il bordo sinistro del piano intermedio fino alla presa.`,"1nymzxl":`Spela 5 mm dei quattro capi liberi. Avvita i due rossi sotto la vite + dello spinotto e i due neri sotto la −, poi infila lo spinotto nella presa DC dell’UNO, girato in modo che il + sia in alto.`,f3jc5e:`Spela 5 mm dei quattro capi liberi. Avvita i due rossi sotto la vite + dello spinotto e i due neri sotto la −, poi infila lo spinotto nella presa DC della scheda di espansione, girato in modo che il + sia in alto.`,hhvzfi:`Al banco, salda la resistenza da 220 Ω in serie al piedino lungo (+) del LED. Taglia a metà un cavetto rosso e uno nero. Salda una metà rossa all’estremo libero della resistenza e una metà nera al piedino corto del LED.`,"1qz1083":`Piega piatti i due pin del cicalino. Salda l’altra metà rossa al + (il pin più lungo, segnato sopra) e l’altra metà nera al −.`,"110bbxt":`Piega piatti i due pin del cicalino e salda l’altra metà rossa al + (il pin più lungo, segnato sopra). Salda il collettore del transistor al pin − e una resistenza da 1 kΩ alla sua base, poi mezzo cavetto arancione alla resistenza e l’altra metà nera all’emettitore. Restringi un’unica guaina su transistor e resistenza. Controlla quale piedino è quale sul datasheet del tuo transistor.`,"1avlub7":`Controlla che nessuna saldatura scoperta possa toccarne un’altra e che l’interruttore sia spento. Poi metti le due celle nel portabatterie, ogni estremità + dove il portabatterie indica +. Accendi per un attimo: devono accendersi sia i LED di alimentazione del controller sia quelli del driver.`,k2hc2b:`Cablaggio`,s234wa:`Collega i fili`,"1po8toc":`Ogni sensore e attuatore si collega a un connettore G / V / S dello shield, quindi condividono tutti la massa dell’UNO; la massa del driver viene dalla batteria, che è la stessa massa attraverso lo spinotto DC. I pin sono scelti in base a dove si trova ogni pezzo, così i fili si allargano dai connettori senza incrociarsi. Lavora in quest’ordine, a interruttore spento: prima il LED, in basso all’estremità sinistra del connettore, e per ultimi i quattro fili del sensore, perché passano ad arco sopra tutto il resto. Un cavetto si innesta un’estremità alla volta: spingi una presa fino in fondo sul suo pin, piega il filo, innesta l’altra. Passa il mouse su una riga per vedere il filo sul modello.`,"1ylwoyd":`Ogni sensore e attuatore si collega a un connettore G / V / S della scheda di espansione, quindi condividono tutti la massa dell’ESP32; la massa del driver viene dalla batteria, che è la stessa massa attraverso lo spinotto DC. I pin sono scelti in base a dove si trova ogni pezzo, così i fili si allargano dai connettori senza incrociarsi. Lavora in quest’ordine, a interruttore spento: prima il LED, in basso all’estremità sinistra del connettore, e per ultimi i fili del sensore, perché passano ad arco sopra tutto il resto. Un cavetto si innesta un’estremità alla volta: spingi una presa fino in fondo sul suo pin, piega il filo, innesta l’altra. Passa il mouse su una riga per vedere il filo sul modello.`,"10tvb2g":`D5 e D11 portano la velocità di ciascun lato: sono pin PWM che continuano a funzionare mentre gira la libreria Servo (che si prende il Timer1, disattivando il PWM su D9 e D10). D6 e D12 portano la direzione. Il servo e il cicalino usano A5 e A0 come normali pin digitali. Tutti i pin G sono collegati tra loro, e così tutti i pin V: GND e VCC del sensore possono andare su quelli più vicini.`,it0an4:`Il partitore da 1 kΩ / 2 kΩ trasforma l’impulso Echo da 5 V in 3.3 V (5 V × 2 ⁄ 3). Echo usa GPIO 35, uno dei pin di solo ingresso (34–39): deve soltanto leggere. Il cicalino è alimentato dal pin V a 5 V e il transistor lo commuta, perché 3.3 V sono meno di quanto serve a un cicalino da 5 V. Le uscite evitano GPIO 0, 2, 5, 12, 14 e 15, che sono pin di strapping o pulsano mentre l’ESP32 si avvia. Tutti i pin G sono collegati tra loro, e così tutti i pin V.`,"16ffufp":`LED: attaccalo vicino all’angolo anteriore sinistro del controller · rosso → S · nero → G`,"55vkwv":`Driver A-IA / A-IB (sinistra)`,"1wr2rcy":`Driver B-IA / B-IB (destra)`,"12y58k1":`Cavo del servo (marrone G, rosso V, arancione S)`,"1xjcvwz":`Cicalino: attaccalo sul davanti del piano superiore · rosso → S · nero → G`,"1h6hx3u":`HC-SR04 Trig → S · VCC → V · GND → G di D2`,zvbj2f:`HC-SR04 Echo`,"83uabx":`Cicalino: attaccalo sul davanti del piano superiore · rosso → V · arancione (base) → S · nero (emettitore) → G`,"1eb7xia":`HC-SR04 Trig → S · VCC → V · GND → G di GPIO 34`,"1ig2p4r":`HC-SR04 Echo: taglia il suo cavetto a 4.5 cm da un’estremità · 1 kΩ tra i due pezzi · 2 kΩ verso 4.7 cm tagliati dall’estremità di un cavetto nero · pezzi corti → S e G`,xoaiok:`Codice`,"1if8prf":`Programma`,"1g03ums":`Carica il codice`,"1bv2ey7":`Due sketch. Il test del cablaggio prova ogni pezzo a turno, così vedi che ognuno è collegato e che entrambi i lati girano nel verso giusto. L’evita ostacoli è il programma dell’auto: avanza finché qualcosa è più vicino di 22 cm, guarda a destra e a sinistra con la testa e gira verso il lato con più spazio.`,"8lzj5q":`Questo firmware trasforma l’ESP32 in un access point Wi-Fi. Esegue i comandi che RoboKit invia (guida, velocità, modalità, servo, LED e cicalino), si ferma se smettono di arrivare e rimanda la distanza e lo stato dei motori 10 volte al secondo. In modalità Auto evita gli ostacoli da solo, con la stessa routine che esegue il simulatore.`,saufbh:`Quando nulla riflette l’impulso, l’HC-SR04 tiene Echo alto per circa 38 ms (il valore del datasheet; alcuni moduli lo tengono più a lungo). È oltre il timeout di 30 ms, quindi pulseIn() restituisce 0. L’evita ostacoli lo conta come 400 cm, “libero”, non come “a contatto”. Il fascio è stretto, quindi l’auto può urtare un angolo che non ha mai visto: una lettura che smette di cambiare mentre le ruote spingono le dice che è bloccata. E quando è di nuovo bloccata subito dopo una svolta, gira ancora dalla stessa parte invece di tornare indietro: in un angolo girerebbe altrimenti a sinistra, a destra, a sinistra all’infinito.`,"11hew0t":`ledcAttach() e ledcWrite(pin, duty) sono l’API di arduino-esp32 3.x; le vecchie chiamate ledcSetup() e ledcAttachPin() della 2.x non compilano più. Il fascio del sensore è stretto, quindi in Auto l’auto può urtare un angolo che non ha mai visto: una lettura che smette di cambiare mentre le ruote spingono le dice che è bloccata. E quando è di nuovo bloccata subito dopo una svolta, gira ancora dalla stessa parte invece di tornare indietro: in un angolo girerebbe altrimenti a sinistra, a destra, a sinistra all’infinito.`,"3zk06m":`Nell’Arduino IDE scegli Tools → Board → Arduino UNO e la porta giusta. Entrambi gli sketch usano la libreria Servo, inclusa nell’IDE.`,j0z2nr:`Solleva l’auto su un supporto in modo che le quattro ruote non tocchino il tavolo. Carica il test del cablaggio, accendi la batteria e apri il Serial Monitor a 115200 baud. Osserva ogni riga numerata mentre accade: LED e bip, testa a destra, a sinistra e al centro, poi ogni lato avanti e indietro.`,"1dz2oap":`Correggi ciò che non corrispondeva (vedi l’elenco qui sotto). Poi carica l’evita ostacoli, scollega il cavo USB, metti l’auto sul pavimento e accendi: aspetta due secondi, poi parte.`,"4czqhs":`Cambia TURN_MS nello sketch finché ogni svolta è di circa un quarto di giro sul tuo pavimento.`,rgjhux:`Nell’Arduino IDE aggiungi https://espressif.github.io/arduino-esp32/package_esp32_index.json in File → Preferences → Additional boards manager URLs. Poi installa “esp32 by Espressif Systems” versione 3.x dal Boards Manager e scegli ESP32 Dev Module.`,"118rr9r":`Dal Library Manager installa l’ultima versione di “WebSockets” di Markus Sattler e “ArduinoJson” versione 7 di Benoit Blanchon.`,nbb8bl:`Carica, poi solleva l’auto in modo che le quattro ruote non tocchino il tavolo e accendi la batteria. Collegati alla rete Wi-Fi “RoboKit” (password drive1234), vai al passo 10 e connettiti da Impostazioni → Auto vera (Wi-Fi dell’ESP32).`,srtywe:`Prova ogni comando a turno: LED, cicalino, il cursore del servo, poi W A S D. Se un lato gira al contrario, vedi l’elenco qui sotto. Poi metti l’auto sul pavimento, prova Auto e cambia TURN_MS finché ogni svolta è di circa un quarto di giro.`,sp50jr:`Non si accende nulla quando accendi`,"1gg4m0p":`Spegni. Controlla che le celle siano cariche e nel verso giusto, che i fili rossi siano sotto la vite + dello spinotto e che l’interruttore sia collegato tra il pin centrale e un pin esterno.`,"9crnd5":`Un lato gira al contrario nel test`,"1mf4jfi":`Scambia i due fili di quel lato nel suo morsetto: MOTOR-A è il lato sinistro, MOTOR-B il destro.`,"1gcvytv":`Una ruota gira contro la compagna`,"76bppn":`Scambia i due fili di quel motore dove sono attorcigliati a quelli dell’altro motore.`,kakgt9:`La riga 3 fa girare le ruote di destra`,"95tfvz":`Le due coppie di cavetti sono invertite: A-IA / A-IB vanno a D11 / D12, B-IA / B-IB a D5 / D6.`,"1yvpqg9":`La testa guarda prima a sinistra`,"3fc0ov":`Alcuni servo girano al contrario: scambia 20 e 160 negli sketch.`,"1ymivbo":`La distanza è sempre 0.0 cm`,"1wzcqly":`Non torna nessuna eco. Controlla che Trig sia su D4 ed Echo su D3, e che VCC e GND del sensore siano su un pin V e un pin G. Legge 0 anche quando non c’è nulla entro circa 4 m.`,lg1f33:`L’UNO si riavvia quando partono i motori`,gp3cr0:`La tensione della batteria cala: ricarica le celle. Un condensatore da 470–1000 µF tra V e G sullo shield (attento alla polarità) aiuta l’alimentazione a 5 V a superare i cali.`,"13n04wo":`L’auto ronza ma non gira sul posto`,y7q52i:`Girare trascina di lato tutti e quattro gli pneumatici e richiede più spinta che andare dritto: alza SPIN verso MAX_PWM e ricarica le celle.`,hvphiw:`Devia da un lato`,ittf4s:`Non esistono due motori uguali. Rallenta il lato più veloce: per un’auto che devia a destra, drive(CRUISE - 10, CRUISE).`,"19do8xl":`Il caricamento si ferma su “Connecting…”`,hn5crr:`Tieni premuto il pulsante BOOT del DevKit finché il caricamento non inizia, e controlla che il cavo USB trasmetta dati, non solo alimentazione.`,"144ggw6":`RoboKit non si connette`,"1wm6oj5":`Un lato gira al contrario`,"1buhj6h":`Sinistra e destra sono invertite`,"1s6olzj":`Le due coppie di cavetti sono invertite: A-IA / A-IB vanno a GPIO 26 / 27, B-IA / B-IB a GPIO 33 / 25.`,svln7p:`In Auto, la testa guarda prima a sinistra`,"1ki0m9i":`Alcuni servo girano al contrario: scambia 20 e 160 in autoStep().`,"6xg3a":`La distanza è sempre 400 cm`,"7himiv":`Non torna nessuna eco. Controlla che Trig sia su GPIO 32, che Echo arrivi a GPIO 35 attraverso il partitore e che VCC del sensore sia su un pin a 5 V. Legge 400 anche quando non c’è nulla entro circa 4 m.`,ksb87p:`Il cicalino resta muto`,"9czfii":`Controlla i piedini del transistor sul suo datasheet (l’ordine cambia da un tipo all’altro), e che il + del cicalino sia su un pin a 5 V.`,igpqu0:`L’ESP32 si riavvia quando partono i motori`,owaty5:`La tensione della batteria cala: ricarica le celle. Un condensatore da 470–1000 µF tra un pin a 5 V e G (attento alla polarità) aiuta l’alimentazione a superare i cali.`,"1u5gnnb":`Girare trascina di lato tutti e quattro gli pneumatici e richiede più spinta che andare dritto: aumenta la velocità e ricarica le celle.`,uak3xr:`1 · Test del cablaggio`,"1jz093b":`2 · Evita ostacoli`,"129dlzg":`Firmware`,ussxe7:`Simula`,"17ssthc":`Guidala`,bmzqy4:`L’auto simulata ha gli stessi pezzi della tua. Guidala nell’arena di prova, poi passa ad Auto: esegue la stessa routine dello sketch evita ostacoli. Si ferma e suona davanti a un ostacolo, guarda a destra e a sinistra, gira verso il lato con più spazio e indietreggia quando è bloccata.`,"189d210":`L’auto simulata risponde agli stessi comandi che RoboKit invia al tuo ESP32, e Auto esegue la stessa routine del firmware. Quando la tua auto è costruita, passa a essa in Impostazioni → Auto vera (Wi-Fi dell’ESP32).`,olmdkx:`Ruota, 65 mm`,psly3z:`Trazione`,vffqvh:`Uno pneumatico in gomma su un cerchio di plastica. Il mozzo ha un incavo con due facce piane che si infila sull’albero di uscita del motore TT, così la ruota non può slittare. Quando l’auto gira sul posto gli pneumatici strisciano di lato, quindi l’aderenza conta.`,jq4v4c:`Mozzo`,mq93xq:`incavo a doppia faccia piana per l’albero del motore TT`,"1cgpuek":`Distanza per giro`,esl998:`≈ 20.4 cm (π × 6.5 cm)`,"11yszgp":`Motoriduttore TT`,m5llum:`Un piccolo motore DC a spazzole che aziona un riduttore in plastica 1:48. Inverti la corrente e la ruota gira dall’altra parte; abbassa la tensione media con il PWM e rallenta.`,"525amd":`Tensione`,"226us9":`Rapporto di riduzione`,jpnnsq:`≈ 200 rpm a 6 V, a vuoto`,"1dw4k8q":`Corrente`,"1p9wnb6":`≈ 150 mA a vuoto · fino a ≈ 1.5 A in stallo a 6 V`,cdauuh:`Coppia di stallo`,"1gzxf67":`≈ 0.8 kg·cm a 6 V`,ign4wl:`Corpo`,mad9cv:`Albero`,"14e36jb":`Ø 5.5 mm con due facce piane a 3.7 mm di distanza, sporgente da entrambi i lati`,feutd2:`Fissaggio`,"183nrmx":`due fori Ø 3 mm a 17.5 mm di distanza, 20 mm dietro l’albero`,"108seeu":`Staffa motore`,"1mquwkf":`Telaio`,"10qeeg1":`Un pezzo di acrilico a forma di T. Il gambo sale attraverso il piano inferiore accanto al riduttore e la testa resta sotto, così non può sfilarsi. Ne va una per lato di ogni motore, e due bulloni lunghi passano attraverso entrambe le staffe e i due fori di fissaggio del riduttore.`,"1kk17cw":`Materiale`,"1me4wyg":`acrilico`,st0e1p:`Per motore`,"8uzq1j":`2 staffe · 2 bulloni M3 × 30 + dadi`,"1am47c9":`Montaggio`,v6cwyh:`da sotto il piano: quella interna in una fessura, quella esterna in una tacca sul bordo`,"723pu9":`Porta i quattro motori e gli otto distanziali del piano intermedio. Una fessura e una tacca sul bordo accanto a ogni motore accolgono le due staffe di quel motore.`,"1n7meho":`Dimensioni (questo modello)`,r4lxco:`Il pavimento dell’elettronica. La lunga fessura al centro fa salire i fili dei motori da sotto, e il foro rettangolare sul davanti accoglie il servo; la tacca all’estremità è per il cavo del servo.`,"11vqw8c":`25 mm sopra il piano inferiore`,"1957t19":`Piano superiore`,"2ljc6y":`Un piano lungo la metà, nella parte posteriore, che regge il pacco batterie, l’interruttore e il cicalino sopra l’elettronica.`,"1ytak7b":`1.5 cm sopra il piano intermedio`,"1ey525v":`Distanziale in ottone, M3`,"7je4w9":`Distanziali esagonali filettati alle due estremità. Tengono separati i piani e sollevano i circuiti dall’acrilico, così nulla sul loro lato inferiore lo tocca.`,"1t2znv5":`Filettatura`,i9dhsi:`M3, femmina–femmina`,"1cazjzs":`piano inferiore → intermedio (supera i motori da 22 mm)`,rni6ay:`piano intermedio → superiore`,"1dz3bjd":`scheda del controller`,"1erre2c":`Viti`,"7fsd49":`una M3 × 6 mm a ogni estremità, 32 in tutto`,pmsrct:`Fili dei motori`,h0ivdz:`Un filo rosso e uno nero da ogni motore: il rosso sulla linguetta più vicina al centro dell’auto, il nero su quella più vicina alla ruota. I due motori di ciascun lato sono collegati in parallelo a un canale del driver, rosso con rosso e nero con nero, così girano sempre insieme.`,"148isqp":`circa 15 cm ciascuno`,"88dh10":`Coppia sinistra`,"1hr3y9w":`MOTOR-A`,"1gp3zrj":`Coppia destra`,"1il2rct":`MOTOR-B`,"4iibl6":`Un lato gira al contrario?`,"1p9lbgb":`scambia le sue due coppie nel morsetto`,"2380z5":`Una ruota contro la compagna?`,h5sbfv:`scambia i due fili di quel motore`,"19qn9l6":`Driver motori L9110S`,"82whm4":`Elettronica`,"12ibf8u":`Due chip a ponte H L9110S, uno per canale. Ogni canale ha due ingressi: IA alto e IB basso fanno girare il motore in un verso, IA basso e IB alto nell’altro, e se sono uguali si ferma. Il PWM su un ingresso imposta la velocità.`,"25ul91":`Alimentazione (VCC)`,m2phlf:`800 mA per canale (1.5–2 A di picco)`,"17s6ks8":`Ingressi`,d0m2ee:`A-IA, A-IB, B-IA, B-IB · logica a 3.3 V o 5 V`,"4swwow":`Connettore`,oja0mi:`B-IA · B-IB · GND · VCC · A-IA · A-IB (pin piegati ad angolo retto)`,"1xbblqt":`circa 29 × 23 mm, fori di fissaggio Ø 3 mm (le misure variano secondo il venditore)`,"189a81e":`Una scheda con microcontrollore ATmega328P. Esegue il tuo sketch, legge il sensore e decide cosa fanno i motori.`,"1ebaepz":`ATmega328P @ 16 MHz`,"16qkmtv":`Livello logico`,eslzkd:`Pin PWM`,oopaku:`Memoria`,"8hfwsd":`32 KB flash · 2 KB RAM`,"1jzh7y5":`Alimentazione`,"1vbs2jm":`7–12 V sulla presa DC (consigliati)`,"1hxwxrt":`Corrente per pin`,xms582:`20 mA consigliati · 40 mA massimo assoluto`,"1n28mf4":`Si innesta sopra l’UNO e porta ogni pin su un connettore G / V / S a 3 pin (massa, 5 V, segnale), così un servo o un sensore si collega direttamente con la propria massa e alimentazione.`,e8ir2h:`Connettori`,d0uaj4:`D0–D13 e A0–A5, ciascuno G · V · S`,"1iy90zn":`Pin V`,ohp32m:`5 V dall’UNO finché il jumper SEL è montato`,"1y4aysj":`Senza il jumper`,gi4ocs:`V arriva dal morsetto a vite dello shield`,"1thlwjq":`Attenzione`,"1fzsig9":`non alimentare mai il morsetto a vite con SEL montato`,"1kft85q":`Extra`,"1e4238k":`connettori I²C e seriale`,"1jeelmn":`ESP32 DevKit + scheda di espansione`,"8jd2d6":`Un microcontrollore dual-core con Wi-Fi e Bluetooth, inserito in una scheda di espansione che aggiunge una presa DC con regolatore e un connettore G / V / S per ogni pin.`,"1inmx8d":`Modulo`,qx458t:`ESP32-WROOM-32 · fino a 240 MHz`,"7ra2ga":`3.3 V, non tollera i 5 V`,"1chl2hi":`qualsiasi pin di uscita (LEDC)`,"7fk3dd":`Wireless`,"1b7zmuj":`Wi-Fi 802.11 b/g/n · Bluetooth`,pawwts:`≈ 6.5–12 V sulla presa DC (controlla la tua scheda)`,yzyhje:`3.3 V o 5 V, scelti con un jumper`,"7wntef":`Micro servo SG90`,mni0ct:`Un piccolo motore, un riduttore e un sensore di posizione in un unico involucro. Si aspetta un impulso ogni 20 ms (50 Hz); la durata dell’impulso imposta l’angolo: 1.5 ms è il centro, e circa 0.5–2.4 ms coprono da 0° a 180°.`,wvoosj:`Coppia`,"1e13gca":`≈ 0.1 s per 60°`,"1yo9wk7":`Dimensioni · peso`,"1oaes5p":`23 × 12 × 29 mm · 9 g`,"1b34x3l":`Fili`,"1qalf36":`marrone GND · rosso V+ · arancione segnale`,"1bshntj":`Staffa per servo dell’HC-SR04`,"1yr5sge":`Si avvita alla squadretta del servo e tiene l’HC-SR04 per due dei suoi fori d’angolo, così il sensore gira con il servo e il suo fascio resta orizzontale.`,"1t4m9bk":`Fissaggio`,mnle4w:`viti della squadretta del servo`,"1yzxd81":`Regge`,"1fp9bdu":`l’HC-SR04 per due dei suoi fori d’angolo, su distanziali`,"1yozvc2":`Altri tipi`,"16fhes5":`molte staffe afferrano invece il sensore per i suoi due trasduttori`,c8gdr7:`Un impulso di 10 µs su Trig fa emettere a un trasduttore otto cicli a 40 kHz; l’altro ascolta. Echo resta poi alto per il tempo che il suono ha impiegato ad andare e tornare, quindi cm = µs ÷ 58 (343 m/s, diviso a metà).`,"198uyr6":`Portata`,"3xsn4q":`Fascio`,"1gw4v0v":`meno di 15°`,"1oy2zwu":`Alimentazione`,"1m7niep":`Frequenza degli impulsi`,"7gsn1j":`uno ogni 60 ms o più lento`,npm5w4:`Pin (davanti, sinistra → destra)`,pyp646:`VCC · Trig · Echo · GND con i pin in basso; montato con i pin in alto, come qui: GND · Echo · Trig · VCC`,cr1wqh:`Pacco Li-ion 2 × 18650`,"1fdnj4z":`Due celle in serie: 8.4 V da cariche, 7.4 V nominali, circa 6 V da scariche. Usa celle protette, non cortocircuitarle mai e caricale con un vero caricatore Li-ion.`,w63ube:`7.4 V nominali (6–8.4 V)`,serueh:`Capacità`,"1lup9sh":`2000–3500 mAh (celle originali)`,"7l22en":`Portabatterie`,"1ka7i4l":`2 posti, in serie`,"1h1ba5m":`le celle protette sono qualche mm più lunghe; controlla che entrino`,h4px5m:`Interruttore di alimentazione`,bs7ocz:`Interrompe il filo + della batteria, così tutta l’auto è spenta. È collegato tra il pin centrale e un pin esterno: il filo rosso del portabatterie su uno, il filo verso lo spinotto sull’altro. Sta di lato su nastro in gommapiuma sul bordo sinistro del piano superiore, leva verso l’esterno, dove un dito può raggiungerlo.`,"1m2zofh":`Tipo`,"69jc9h":`interruttore a slitta SPDT usato come acceso/spento`,w3vkqt:`Pin`,"1owufyi":`tre in fila: esterno · comune · esterno`,fph5dc:`Portata nominale`,"1bpycfc":`scegline uno da ≥ 2 A DC`,k3s7zg:`Cicalino attivo, 5 V`,"177ed2m":`Segnalazione`,jfbt4g:`Ha un oscillatore interno: porta il pin a HIGH e suona a un tono fisso, senza bisogno di codice tone(). Assorbe fino a circa 25–30 mA: dentro il massimo assoluto di 40 mA del pin ma sopra i 20 mA di solito consigliati, quindi comandarlo con un transistor NPN è l’abitudine più delicata.`,xscire:`Ha un oscillatore interno: alimentalo e suona a un tono fisso. I cicalini attivi da 5 V funzionano da circa 3.5–4 V in su, quindi un pin a 3.3 V non può farlo suonare in modo affidabile. Qui è alimentato dal pin V a 5 V e lo commuta un transistor NPN, comandato da GPIO 21.`,"1p7q9i9":`Tono`,"17n9x61":`≈ 2.3 kHz`,z19kz7:`Tensione nominale`,"2tl42a":`5 V (funziona da ≈ 3.5–4 V in su, secondo il produttore)`,"1udh5u4":`≈ 25–30 mA a 5 V`,"1xat3vm":`a 7.6 mm di distanza`,"1yzktex":`Polarità`,"1tmcwg9":`pin più lungo / “+” sopra = +`,i8lb7k:`LED rosso da 10 mm`,"513nhj":`La corrente scorre dal piedino lungo (anodo, +) al piedino corto (catodo, −, dalla parte del lato piatto del bordo). Serve sempre una resistenza in serie. Qui sta di lato vicino all’angolo anteriore sinistro del controller e illumina verso la sinistra dell’auto.`,"17jikfo":`Tensione diretta`,"1g61wql":`20 mA max`,u532rf:`Resistenza da 220 Ω`,"17qhgqf":`Limita la corrente del LED: (5 V − 2 V) ÷ 220 Ω ≈ 14 mA. Le bande colorate si leggono rosso, rosso, marrone: 2, 2 e × 10 = 220 Ω.`,"1kwszon":`Limita la corrente del LED: (3.3 V − 2 V) ÷ 220 Ω ≈ 6 mA. Le bande colorate si leggono rosso, rosso, marrone: 2, 2 e × 10 = 220 Ω.`,zzpczz:`Bande`,"7ytjo4":`rosso · rosso · marrone · oro`,"1llx3uw":`Tolleranza`,"3389ey":`Partitore Echo · 1 kΩ + 2 kΩ`,i8pnlw:`L’uscita Echo dell’HC-SR04 arriva a 5 V, ma i pin dell’ESP32 accettano al massimo 3.3 V. Due resistenze in serie da Echo a massa formano un partitore: il GPIO legge la tensione sulla 2 kΩ, 5 V × 2 kΩ ÷ (1 kΩ + 2 kΩ) ≈ 3.3 V.`,"15yc2v4":`Bande della 1 kΩ`,"89urq0":`marrone · nero · rosso · oro`,"1ypqwgn":`Bande della 2 kΩ`,"1ywrkmt":`rosso · nero · rosso · oro`,"12k1o0e":`Echo → 1 kΩ → GPIO 35 · 2 kΩ da GPIO 35 a G`,aarp77:`Serve per`,"15e8vss":`solo ESP32`,"1aqlq1n":`Transistor del cicalino · NPN + 1 kΩ`,vudz42:`Un transistor NPN funziona da interruttore: una piccola corrente nella base lascia scorrere una corrente più grande dal collettore all’emettitore. GPIO 21 pilota la base attraverso 1 kΩ, (3.3 V − 0.7 V) ÷ 1 kΩ ≈ 2.6 mA, più che sufficienti per commutare i ≈ 30 mA del cicalino dal pin a 5 V.`,"1gy1kba":`Transistor`,"62rwh2":`PN2222A, S8050 o NPN simile`,"1tlwyig":`Collettore`,"18vf2cp":`− del cicalino`,"19phq7s":`Base`,hrttng:`1 kΩ → S di GPIO 21`,"10ztoj1":`Emettitore`,"1m0unsb":`G di GPIO 21`,"16l0jzg":`Piedini`,v4q23:`controlla la piedinatura sul suo datasheet`,gy95h:`Filo di collegamento`,"170hkbj":`Filo rosso e nero a trefoli per i fili dei motori. Taglialo a misura man mano.`,"19d4ccc":`Rosso`,ch832v:`la linguetta più vicina al centro dell’auto, su ogni motore`,bxogn8:`Nero`,"1xdely8":`la linguetta più vicina alla ruota`,"114bxvb":`Cavetti jumper femmina–femmina`,tq3ghm:`Cavetti Dupont con una presa a entrambe le estremità che si innestano su pin a passo 2.54 mm. Gli ingressi del driver e il sensore usano un cavetto intero per pin. Tagliato in due, un cavetto dà fili con una presa a un’estremità: per i pezzi saldati (il LED, il cicalino) e per l’alimentazione del driver, i cui altri capi vanno sotto le viti dello spinotto.`,xe6ekx:`Passo`,terfe0:`15 cm (vanno bene anche da 20 cm: lasciano anse più grandi)`,q9r4h7:`Usati interi`,"16oowgw":`8: quattro ingressi del driver, quattro pin del sensore`,"1rf1gzr":`7: quattro ingressi del driver, tre pin del sensore`,onu7hf:`Tagliati`,"38aacf":`4: un rosso e un nero a metà per i fili del LED e del cicalino, un rosso e un nero a 12.5 cm da un’estremità per l’alimentazione del driver`,"3iidc0":`6: un rosso e un nero a metà per i fili del LED e del cicalino, un arancione a metà per la base del transistor, un rosso e un nero a 11 cm da un’estremità per l’alimentazione del driver, e il filo Echo del sensore per il suo partitore`,"14fe75h":`Cavetti jumper · sensore a ultrasuoni`,f96u6l:`Quattro cavetti dal connettore del sensore, che è in alto, tornano ad arco verso lo shield. Per VCC e GND va bene qualsiasi pin V e qualsiasi pin G: si usano i più vicini, così i quattro fili si allargano fianco a fianco.`,tuihok:`Quattro fili dal connettore del sensore, che è in alto, tornano ad arco verso la scheda di espansione. Echo è un segnale a 5 V, quindi passa per un partitore da 1 kΩ / 2 kΩ (saldato nel suo cavetto, sotto guaina termorestringente) prima di arrivare al GPIO a 3.3 V.`,ftyyiy:`V di D4`,"1xuokt7":`Trig`,o3rtpx:`S di D4`,gi87tw:`Echo`,m5ulv4:`S di D3`,y9urxb:`G di D2`,"1n4125d":`V di GPIO 32 (impostato a 5 V)`,p5iwlb:`S di GPIO 32`,"1aj3mnm":`1 kΩ → S di GPIO 35 · 2 kΩ da lì al suo G`,p0bbcd:`G di GPIO 34`,"1kn37ri":`Cavetti jumper · driver motori`,oiporr:`I quattro ingressi del driver. Ogni coppia controlla un lato dell’auto: IA porta la velocità, su un pin PWM, e IB la direzione.`,z48w8g:`I quattro ingressi del driver, ciascuno su un pin che supporta il PWM. Ogni coppia controlla un lato dell’auto.`,"11ubulz":`A-IA / A-IB (sinistra)`,jf4uze:`B-IA / B-IB (destra)`,"15oeqsr":`Cavo del servo`,wowqjs:`Il cavo a tre fili del servo. Scende attraverso il foro e risale dalla fessura accanto, torna indietro lungo il piano accanto al controller e arriva al connettore posteriore; ciò che avanza è ripiegato sotto il piano. La sua spina a 3 vie entra in un connettore G / V / S in un colpo solo: marrone su G.`,v89fad:`Il cavo a tre fili del servo. Scende attraverso il foro e risale dalla fessura accanto, torna indietro lungo il piano accanto al controller e arriva al connettore posteriore; ciò che avanza è ripiegato sotto il piano. La sua spina a 3 vie entra in un connettore G / V / S in un colpo solo: marrone su G. La fila V deve essere impostata a 5 V.`,r6nyn:`Marrone`,"1u2gqme":`Arancione (segnale)`,"1qoi1mz":`S di A5`,ovg5ed:`S di GPIO 23`,"1uovlnp":`Fili del LED`,"1mffxae":`Mezzo cavetto rosso e mezzo nero, saldati al LED con una presa all’altra estremità. L’anodo passa per la resistenza da 220 Ω verso un pin di segnale; il catodo va a massa.`,elp8sy:`Anodo (tramite 220 Ω)`,k62hvj:`S di D13`,ilk009:`Catodo`,k48vv7:`G di D13`,tbj8zu:`S di GPIO 13`,imqrdy:`G di GPIO 13`,"1indwkw":`Fili del cicalino`,"1c2cbqo":`Mezzo cavetto rosso e mezzo nero saldati ai pin del cicalino. Porta il filo + a HIGH per suonare.`,epsmo4:`Il cicalino sta tra il pin V a 5 V e il transistor. Porta GPIO 21 a HIGH e il transistor collega il − del cicalino a massa, così suona.`,"1rigupw":`S di A0`,"1yvwce0":`G di A0`,"1tndblu":`V di GPIO 21 (5 V)`,i73cl5:`collettore del transistor`,a4pty4:`Base (tramite 1 kΩ)`,obgy0f:`S di GPIO 21`,g663eg:`Cablaggio di alimentazione`,wp3j1m:`Tutto si incontra in uno spinotto DC con due morsetti a vite, infilato nella presa DC dell’UNO. Il + della batteria arriva al morsetto + attraverso l’interruttore; il − della batteria va dritto al morsetto −. Un secondo filo rosso e un secondo nero sotto le stesse due viti portano la tensione della batteria ai pin VCC e GND del driver. Il driver non può essere alimentato dai pin a 5 V dello shield: sono forniti dal regolatore dell’UNO, che regge al massimo qualche centinaio di mA.`,"1gazt2h":`Tutto si incontra in uno spinotto DC con due morsetti a vite, infilato nella presa DC della scheda di espansione. Il + della batteria arriva al morsetto + attraverso l’interruttore; il − della batteria va dritto al morsetto −. Un secondo filo rosso e un secondo nero sotto le stesse due viti portano la tensione della batteria ai pin VCC e GND del driver. Il driver non può essere alimentato dai pin a 5 V della scheda: sono forniti dal suo regolatore, che regge al massimo qualche centinaio di mA.`,"1wuyp3l":`+ della batteria (tramite interruttore)`,"161fdmk":`− della batteria = GND`,"6j9255":`Spinotto`,"1qkac6a":`spinotto a barile 5.5 × 2.1 mm, centro +, con morsetti a vite`,"1s864ea":`Sotto ogni vite`,wj14kx:`due fili: uno dalla batteria, uno verso il driver`,oz5l6a:`Evita ostacoli`,zj0mwn:`Misura la distanza`,"9jogsy":`A ogni giro di loop() il sensore lancia un ping. Lo sketch annota anche quando la lettura è cambiata per l’ultima volta di più di {changeCm} cm: una lettura che resta ferma mentre le ruote spingono è il segno che l’auto è bloccata.`,"1va2b8a":`Strada libera?`,yssn5p:`La strada è libera?`,zou1hc:`Libera significa niente più vicino di {stopCm} cm (STOP_CM) e una lettura che cambia ancora. Allora l’auto prosegue e chiede di nuovo {pingMs} ms dopo.`,"164owbk":`Prosegui`,"2guryp":`LED spento, entrambi i lati avanti a CRUISE e un’attesa di {pingMs} ms: il sensore ha bisogno di tanto tempo tra due ping. Poi un altro giro.`,l1vybm:`Stop
LED acceso · bip`,ywa890:`Stop, LED acceso, un bip breve`,"17krb65":`Bloccata o incastrata: i motori si fermano, il LED si accende e il cicalino suona per {beepMs} ms.`,"1njcbjw":`Incastrata?`,"6b9vj0":`Incastrata su qualcosa che il fascio non ha visto?`,"12aymoo":`Il fascio del sensore è largo solo circa 15°, quindi l’auto può impigliarsi in un angolo che non ha mai visto. Se la lettura non è cambiata di più di {changeCm} cm per {stuckMsS}, anche se la strada sembrava libera, l’auto è incastrata. (Nessuna eco, 400, non conta mai: lo spazio aperto non è “incastrata”.)`,"7k6lib":`Indietreggia`,ooiwv8:`Si allontana da ciò che la trattiene per {backOffMsS}, e solo dopo si guarda intorno.`,"1d4sv1w":`Guarda a destra, poi a sinistra`,"18crqcc":`La testa gira a {lookRight}° (destra) e a {lookLeft}° (sinistra). Ogni volta il servo ha {settleMsS} per arrivarci prima che il sensore venga letto; entrambe le letture vengono stampate.`,"1r9o4nf":`C’è spazio per girare?`,"122yr22":`Se nessun lato ha {tightCm} cm (TIGHT_CM), qui non c’è spazio per girare.`,"1i7u6tc":`Retromarcia, guarda di nuovo`,"1ik4v71":`Retromarcia e guarda di nuovo`,a0a741:`Chiusa: fa retromarcia per {backMsS} e da lì guarda di nuovo a destra e a sinistra, tutte le volte che serve.`,"1yfjvg4":`Ha appena girato?`,"2jbjim":`Bloccata di nuovo subito dopo una svolta?`,"3dv25u":`La testa torna al centro. Poi: se l’ultima svolta è finita da meno di {againMsS}, l’auto si è mossa appena da quando ha girato.`,"1steplx":`Di nuovo nello stesso verso`,kn4k3y:`Gira di nuovo nello stesso verso`,"1k7wpmb":`Girare al contrario la riporterebbe solo dov’era: in un angolo girerebbe a sinistra, a destra, a sinistra all’infinito. Quindi continua a girare nel verso dell’ultima svolta, qualunque cosa dicano le due letture.`,"1lf2d81":`Il lato con più spazio`,"1u19y2l":`Gira verso il lato con più spazio`,"1n1zre5":`A sinistra se la lettura a sinistra è grande almeno quanto quella a destra, altrimenti a destra.`,"5j8yhm":`Gira`,"4h9f4g":`I due lati girano in versi opposti per TURN_MS ({turnMs} ms, circa un quarto di giro: regolalo per il tuo pavimento). Poi l’auto si ferma, ricorda da che parte ha girato e quando, e loop() ricomincia dall’inizio.`,mz8bk9:`Modalità Auto`,rg9t88:`Dieci volte al secondo loop() lancia un ping con il sensore e tiene la lettura in distance (che va a RoboKit nello stesso momento). In modalità Auto, autoStep() decide poi cosa farne.`,"15ai7e9":`Bloccata significa qualcosa più vicino di {stopCm} cm (STOP_CM). La lettura può avere fino a {sampleMsS}, quindi subito dopo una svolta aspetta {freshMs} ms una lettura presa guardando nella nuova direzione. Altrimenti l’auto continua ad andare.`,"1wwbbaz":`Mentre avanza, dir vale "forward": la fine di loop() lo trasforma nelle velocità dei due motori, alla velocità impostata da RoboKit.`,q8ujdx:`Il fascio del sensore è largo solo circa 15°, quindi l’auto può impigliarsi in un angolo che non ha mai visto. Se la lettura non è cambiata di più di {changeCm} cm per {stuckMsS} mentre avanzava, l’auto è incastrata: indietreggia prima di guardarsi intorno. (Nessuna eco, 400, non conta mai: lo spazio aperto non è “incastrata”.)`,"1e83w8t":`La testa gira a {lookRight}° (destra), poi a {lookLeft}° (sinistra). Ogni lettura viene presa quando il servo ha avuto il tempo di arrivarci, e la testa torna al centro.`,"1pjappa":`Se l’ultima svolta è finita da meno di {againMsS}, l’auto si è mossa appena da quando ha girato. (Attivare Auto riparte da zero: turnedAt vale allora 0.)`,pjp20w:`Girare al contrario la riporterebbe solo dov’era: in un angolo girerebbe a sinistra, a destra, a sinistra all’infinito. Quindi goLeft resta com’è e l’auto gira nel verso dell’ultima svolta, qualunque cosa dicano le due letture.`,ihilws:`I due lati girano in versi opposti per TURN_MS ({turnMs} ms, circa un quarto di giro: regolalo per il tuo pavimento). Poi il LED si spegne, l’ora viene annotata e l’auto riparte.`,"1k1y69x":`4× motore TT`,"15bpusl":`8× staffa motore`,dgwrs0:`Bulloni, dadi e viti M3`,"1mkf3n0":`4× ruota, 65 mm`,"19aemsl":`Driver L9110S`,"123jzux":`cuscinetto di gommapiuma`,a4iz5j:`Scheda di espansione ESP32`,"1al7iyf":`staffa del sensore`,a89ttz:`Servo SG90`,"1alynuo":`squadretta`,"1pbblc6":`Portabatterie 2 × 18650`,muur5i:`2× cella 18650`,"1t10ooq":`interruttore`,"7h9qib":`cicalino attivo`,"1uw5qdo":`spinotto DC`,"1l9u4j2":`16× distanziale M3`,hiufn9:`filo di collegamento`,"1w4hkux":`20× cavetti jumper (F–F, 15 cm)`,"1onzquf":`piano inferiore`,"1h4bzq9":`piano intermedio`,myp2cd:`piano superiore`,pu413r:`I browser bloccano ws:// da una pagina https:// — esegui RoboKit sul tuo computer (npm run dev) per raggiungere l’auto`,tqkecz:`Questa pagina è servita via https, quindi il browser non le permette di aprire ws:// verso l’auto. Per guidare l’auto vera, esegui RoboKit sul tuo computer (npm install, poi npm run dev) e apri http://localhost:5173.`,vqmrol:`Il tuo computer deve essere sulla rete “RoboKit” e RoboKit deve essere aperto via http://, non https://: i browser bloccano ws:// dalle pagine sicure, quindi una copia ospitata online non può raggiungere l’auto. Eseguilo sul tuo computer (npm install finché hai ancora internet, poi npm run dev) e apri http://localhost:5173.`};export{e as default};